import Foundation

/// The workhorse script, compiled into the binary so `prepare` can pipe it over ssh.
public enum HostScript {
    /// The text of `host/macmosh-host`. Generated by `scripts/embed-host-script.sh`.
    public static let source: String = HostScriptSource.text

    /// Read from the script's own `MACMOSH_HOST_VERSION=` line the first time it is used, so the
    /// version is written once. Empty if the script has no such line.
    public static let version: String = {
        let prefix = "MACMOSH_HOST_VERSION="
        for line in source.split(separator: "\n") where line.hasPrefix(prefix) {
            return String(line.dropFirst(prefix.count)).trimmingCharacters(in: CharacterSet(charactersIn: "\"'"))
        }
        return ""
    }()
}
